namespace UnscRelay.Core;
public sealed record ConnectionTemplate(string Id,string Name,string Protocol,int Port,int TimeoutSeconds,int KeepAliveSeconds,string Environment,bool RequirePostQuantumKex,string LocalShell,string NativeKind,bool StorageBrowser=false)
{
 public void Validate(){if(!Guid.TryParseExact(Id,"N",out _)||string.IsNullOrWhiteSpace(Name)||Name.Length>100||Name.Any(char.IsControl)||Protocol is not("ssh" or "sftp" or "rdp" or "vnc" or "local" or "native")||Port is <1 or >65535||TimeoutSeconds is <5 or >120||KeepAliveSeconds is <0 or >3600||Environment is not("sviluppo" or "test" or "produzione")||LocalShell is not("cmd" or "powershell" or "pwsh" or "wsl"))throw new InvalidDataException("Modello di connessione non valido.");if(Protocol=="native"&&NativeKind is not("ssh" or "sftp" or "mosh" or "telnet" or "serial" or "ftp" or "s3" or "rsh" or "xdmcp" or "bash" or "zsh" or "browser" or "file"))throw new InvalidDataException("Client del modello non valido.");if(StorageBrowser&&(Protocol!="native"||NativeKind is not("ftp" or "s3")))throw new InvalidDataException("Browser del modello non valido.");}
 public static ConnectionTemplate Create(ConnectionProfile source,string name){source.Validate();var value=new ConnectionTemplate(Guid.NewGuid().ToString("N"),name.Trim(),source.Protocol,source.Port,source.ConnectTimeoutSeconds,source.KeepAliveSeconds,source.Environment,source.RequirePostQuantumKex,source.LocalShell,source.Native.Kind,source.Storage.Browser);value.Validate();return value;}
 public ConnectionProfile Instantiate(bool network,bool appearance){Validate();return new(){Name=Name,Protocol=Protocol,Port=network?Port:Protocol=="rdp"?3389:Protocol=="vnc"?5900:22,ConnectTimeoutSeconds=network?TimeoutSeconds:20,KeepAliveSeconds=network?KeepAliveSeconds:25,RequirePostQuantumKex=network&&RequirePostQuantumKex,Environment=appearance?Environment:"sviluppo",LocalShell=LocalShell,Native=new(){Kind=NativeKind},Storage=new(){Browser=StorageBrowser},Authentication=StorageBrowser?"password":Protocol=="local"||Protocol=="native"?"auto":"password"};}
}
